589	// checkCampaignClaimWindow 核对每个已领取的下载/安装/回滚操作的首次领取时间
590	// 都落在活动保存的原维护窗口 [start, end) 内：开始时刻包含、结束时刻不包含。
591	// 首次领取必须遵守维护窗口——早于开始或恰好到达、晚于结束的领取记录都使整个
592	// 存储损坏，即使其余状态与结果历史完全自洽、活动仍在执行或已成功/失败结束、
593	// 该操作后来成功、失败或超时，也不能把窗口外的首次领取当作有效进度接受，
594	// 更不能通过挪动领取时间、撤销领取、删去活动或重写进度来消除矛盾。
595	// 这项核对只针对真正首次领取的时刻：尚未领取的操作没有领取时间（等待下载、
596	// 等待安装、等待回滚及未领取便结束的记录），属正常缺省，不参与核对；未开启
597	// 回滚的活动内存中只有缺省的回滚操作标识，不算已领取。已经在窗口内领取的
598	// 操作，后来在窗口外的重复查询、截止前的结果接受以及活动结束时间都不要求
599	// 重新满足窗口。比较按绝对时刻进行，时区写法不同不视为矛盾。
600	func checkCampaignClaimWindow(campaignID string, c *campaignState) error {
601		for _, cd := range c.Devices {
602			ops := []struct {
603				stage string
604				op    *opState
605			}{
606				{StageDownload, &cd.Download},
607				{StageInstall, &cd.Install},
608				{StageRollback, &cd.Rollback},
609			}
610			for _, item := range ops {
611				if !item.op.Claimed {
612					continue
613				}
614				at := item.op.ClaimedAt
615				// 窗口为 [start, end)：恰好到达开始合法，恰好到达结束不合法。
616				// time.Time 的比较按绝对时刻进行，同一时刻的不同时区写法结果相同。
617				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
618					return fmt.Errorf("%w: campaign %s device %s %s first claimed at %s outside maintenance window [%s, %s)",
619						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
620						at.Format(time.RFC3339Nano),
621						c.WindowStart.Format(time.RFC3339Nano),
622						c.WindowEnd.Format(time.RFC3339Nano))
623				}
624			}
625		}
626		return nil
627	}
628	
629	// checkCampaignTimeBaseline 校验活动时间基线（已接受的最新时间）与保存的
630	// 业务记录自洽：基线必须不早于创建时间、任一设备已经领取下载/安装/回滚的
631	// 时间、任一操作首次接受结果的时间、设备当前状态中已记录的时间；活动已结束
632	// 时还必须不早于保存的结束时间。只比较确实存在的记录：尚未领取的操作没有
633	// 领取时间、尚未接受结果的操作没有结果时间、新建且尚未推进的设备允许没有
634	// 状态时间，这些正常缺省值不导致打开失败。比较按绝对时刻进行，相等合法。
635	func checkCampaignTimeBaseline(campaignID string, c *campaignState) error {
636		baseline := c.LastTime
637		bad := func(format string, args ...any) error {
638			msg := fmt.Sprintf(format, args...)
639			return fmt.Errorf("%w: campaign %s time baseline %s %s",
640				ErrCorruptStorage, campaignID, baseline.Format(time.RFC3339Nano), msg)
641		}
642		if baseline.Before(c.CreatedAt) {
643			return bad("before creation time %s", c.CreatedAt.Format(time.RFC3339Nano))
644		}
645		if c.Ended && !c.EndedAt.IsZero() && baseline.Before(c.EndedAt) {
646			return bad("before end time %s", c.EndedAt.Format(time.RFC3339Nano))
647		}
648		for _, cd := range c.Devices {
649			if !cd.At.IsZero() && baseline.Before(cd.At) {
650				return bad("before device %s state time %s",
651					cd.DeviceID, cd.At.Format(time.RFC3339Nano))
652			}
653			// 已领取（含尚未完成）的操作一定接受过携带领取时刻的请求；
654			// 已接受结果的操作还必须比较首次接受结果的时间。未领取/未接受
655			// 的操作对应时间为零值，属正常缺省，跳过比较。
656			ops := []struct {
657				stage string
658				op    *opState
659			}{
660				{StageDownload, &cd.Download},
661				{StageInstall, &cd.Install},
662				{StageRollback, &cd.Rollback},
663			}
664			for _, item := range ops {
665				if !item.op.ClaimedAt.IsZero() && baseline.Before(item.op.ClaimedAt) {
666					return bad("before device %s %s claim time %s",
667						cd.DeviceID, item.stage, item.op.ClaimedAt.Format(time.RFC3339Nano))
668				}
669				if item.op.HasResult && !item.op.At.IsZero() && baseline.Before(item.op.At) {
670					return bad("before device %s %s result time %s",
671						cd.DeviceID, item.stage, item.op.At.Format(time.RFC3339Nano))
672				}
673			}
674		}
675		return nil
676	}
