678	// checkCampaignResultOrder 校验每个已经接受结果的下载/安装/回滚操作，其首次
679	// 结果发生时间都不早于该操作自己的首次领取时间：同一活动、同一设备、同一阶段
680	// 的两个时刻直接比较，成功与失败适用同一规则。结果先于领取在因果上不可能，
681	// 必须使整个存储拒绝打开；不能用其他设备的领取时间、设备影子的最近上报时间、
682	// 活动的最新时间或结束时间替代这两个时刻，也不能通过修改时间、删除结果历史、
683	// 撤销领取或改变设备状态让记录变得合法。后来安装成功或回滚完成同样不能掩盖
684	// 早先阶段的矛盾，因此该核对对仍在执行和已结束的活动都生效。
685	// 只比较该操作自己确实存在的两个时刻：尚未接受结果（含已领取未完成、随后因
686	// 截止超时）的操作没有结果时间，尚未领取的等待步骤没有领取时间，均属正常
687	// 缺省，跳过核对。首次领取时因版本不兼容而直接形成的下载失败，领取与失败
688	// 可以是同一时刻；两时刻相等合法。已领取操作在窗口结束后、截止前提交结果
689	// 不受限制——本核对不要求结果落在维护窗口内。比较按绝对时刻进行，时区写法
690	// 不同不视为矛盾。重复提交不覆盖首次记录，这里使用的就是首次接受的两个时刻。
691	func checkCampaignResultOrder(campaignID string, c *campaignState) error {
692		for _, cd := range c.Devices {
693			ops := []struct {
694				stage string
695				op    *opState
696			}{
697				{StageDownload, &cd.Download},
698				{StageInstall, &cd.Install},
699				{StageRollback, &cd.Rollback},
700			}
701			for _, item := range ops {
702				o := item.op
703				// 未接受结果（含已领取未完成、超时）或未领取的操作不参与核对：
704				// HasResult 为 true 时上方的操作校验已保证 Claimed 且两个时间非零。
705				if !o.HasResult {
706					continue
707				}
708				// time.Time 的比较按绝对时刻进行：结果早于首次领取即损坏，
709				// 相同时刻的不同时区写法结果相同，相等合法。
710				if o.At.Before(o.ClaimedAt) {
711					return fmt.Errorf("%w: campaign %s device %s %s result at %s before first claim at %s",
712						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
713						o.At.Format(time.RFC3339Nano), o.ClaimedAt.Format(time.RFC3339Nano))
714				}
715			}
716		}
717		return nil
718	}
719	
720	// checkSuccessReport 核对一条已接受的安装/回滚成功记录保存的附带上报与
721	// 对应设备影子最近接受的上报之间的关系。序号必须是正整数且不大于设备最近
722	// 接受的序号：缺失、为零或大于设备记录都按损坏处理。两边序号相等时，这条
723	// 成功记录代表的就是设备最近一次上报，其版本、完整上报配置与首次接受结果时
724	// 保存的发生时间必须分别与影子保存的版本、上报配置和最近上报时间一致
725	// （配置按 JSON 语义比较，时间按同一时刻判断，不因时区表示不同而报错）。
726	// 序号更小则是已被后续上报覆盖的历史记录，不要求与当前影子一致。
727	// 设备当前是否在线不影响本核对；下载结果、失败结果与没有成功结果的阶段
728	// 不保存附带上报序号，也不进入本核对。
729	func checkSuccessReport(campaignID string, dd diskDev, o diskOp, stage string, d *deviceState) error {
730		bad := func(format string, args ...any) error {
731			msg := fmt.Sprintf(format, args...)
732			return fmt.Errorf("%w: campaign %s device %s %s success report %s",
733				ErrCorruptStorage, campaignID, dd.DeviceID, stage, msg)
734		}
735		if o.ResultSeq == 0 {
736			return bad("missing report sequence")
737		}
738		if o.ResultSeq > d.LastSeq {
739			return bad("sequence %d not accepted by device (last accepted %d)", o.ResultSeq, d.LastSeq)
740		}
741		if o.ResultSeq == d.LastSeq {
742			if o.ResultVersion != d.Version {
743				return bad("version %s does not match latest reported version %s", o.ResultVersion, d.Version)
744			}
745			if !rawEqual(o.ResultConfig, d.Reported) {
746				return bad("config does not match latest reported config")
747			}
748			if !o.At.Equal(d.LastReportTime) {
749				return bad("time %s does not match latest report time %s",
750					o.At.Format(time.RFC3339Nano), d.LastReportTime.Format(time.RFC3339Nano))
751			}
752		}
753		return nil
754	}
