756	func validDeviceStatus(status string) bool {
757		switch status {
758		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
759			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
760			DeviceAwaitingRollback, DeviceRollingBack,
761			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
762			return true
763		default:
764			return false
765		}
766	}
