768	// isRollbackTerminal 判断状态是否属于回滚相关终态。
769	func isRollbackTerminal(status string) bool {
770		switch status {
771		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
772			return true
773		default:
774			return false
775		}
776	}
777	
778	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
779	func isRollbackFlowStatus(status string) bool {
780		switch status {
781		case DeviceAwaitingRollback, DeviceRollingBack,
782			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
783			return true
784		default:
785			return false
786		}
787	}
788	
789	// validateInstallStageDisk 校验 ready（等待安装）与 installing（正在安装）两种
790	// 设备状态与本设备在本活动中保存的操作进度一致。两种状态都必须已有本设备接受
791	// 的下载成功结果并停留在安装阶段：ready 表示安装从未领取、尚无安装结果；
792	// installing 表示安装已经领取、但还没有接受安装结果。即使操作标识、时间与结果
793	// 历史各自合法，已完成安装（安装成功或失败已有结果）的设备也不能解释成仍在
794	// 等待或正在安装，安装已经领取的记录同样不能停在 ready。核对只看本设备本活动
795	// 的下载/安装操作记录：不能借用同批其他设备的下载成功，也不能用设备当前版本
796	// 恰好等于目标版本替代下载或安装结果。尚未领取安装时没有安装领取时间、尚无
797	// 安装结果时没有结果时间，是正常缺省；设备离线、维护窗口已结束或普通上报改变
798	// 了当前版本都不在此核对范围内。矛盾一律返回 ErrCorruptStorage，拒绝打开整个
799	// 存储，不通过调整状态、撤销领取、删除历史或补造结果消除矛盾。
800	func validateInstallStageDisk(campaignID string, dd diskDev) error {
801		bad := func(msg string) error {
802			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
803		}
804		switch dd.Status {
805		case DeviceReady, DeviceInstalling:
806		default:
807			return nil
808		}
809		if dd.Phase != StageInstall {
810			return bad("install-stage status without install phase")
811		}
812		// 两种状态都必须有本设备在本活动中已接受的下载成功结果。
813		if !(dd.Download.HasResult && dd.Download.Success) {
814			return bad("install-stage status without accepted download success")
815		}
816		switch dd.Status {
817		case DeviceReady:
818			// 等待安装：安装从未领取、尚无安装结果；没有安装领取时间与结果时间
819			// 是正常缺省。安装已领取或已有成功/失败结果都与 ready 矛盾。
820			if dd.Install.Claimed || dd.Install.HasResult {
821				return bad("ready state with install claimed or resulted")
822			}
823		case DeviceInstalling:
824			// 正在安装：安装已经领取，但还没有接受安装结果（成功或失败都不行）。
825			if !dd.Install.Claimed {
826				return bad("installing state without install claim")
827			}
828			if dd.Install.HasResult {
829				return bad("installing state with install result")
830			}
831		}
832		return nil
833	}
834	
835	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
836	func validateRollbackDisk(campaignID string, dd diskDev) error {
837		bad := func(msg string) error {
838			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
839		}
840		rb := dd.Rollback
841		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
842		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
843		if dd.RollbackTarget != "" && !dd.Download.Claimed {
844			return bad("rollback target locked before download claim")
845		}
846		// 已领取下载且尚无下载结果，或已有成功下载结果：回滚目标必须已锁定，
847		// 字段缺失与空串按同一种损坏处理。这项要求不因设备进入安装阶段或
848		// 活动已结束而取消——否则安装失败后会留下没有明确恢复版本的回滚待办。
849		// 不能用当前影子版本、活动目标版本或允许升级列表替代丢失的目标。
850		// 首次领取前复查版本不兼容、直接在下载阶段失败的设备（下载已有失败
851		// 结果）允许没有目标：这种失败不进入安装或回滚。
852		if dd.RollbackTarget == "" && dd.Download.Claimed &&
853			(!dd.Download.HasResult || dd.Download.Success) {
854			return bad("missing locked rollback target")
855		}
856		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
857		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
858			return bad("rollback status without locked target")
859		}
860		// 回滚流程的唯一入口是“已接受本次安装的失败结果”：等待回滚、正在回滚
861		// 以及回滚成功/失败/超时的设备，都必须能从本设备在本活动中已经接受的
862		// 安装结果确认安装失败。安装尚未领取、已领取但没有结果，或安装结果为
863		// 成功，都不能支持任何回滚状态；即使回滚目标非空、操作标识合法、回滚
864		// 结果与历史一致或活动已结束，也必须核对这一前提。当前版本恰好等于旧
865		// 版本、下载失败以及其他设备或其他活动的失败记录都不能代替本次安装失败
866		// （这里只看本设备本活动保存的安装操作结果本身）。
867		installFailed := dd.Install.HasResult && !dd.Install.Success
868		if isRollbackFlowStatus(dd.Status) && !installFailed {
869			return bad("rollback state without accepted install failure")
870		}
871		switch dd.Status {
872		case DeviceAwaitingRollback:
873			// 已接受安装失败、回滚尚未领取：回滚无结果。
874			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
875				return bad("awaiting rollback state mismatch")
876			}
877		case DeviceRollingBack:
878			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
879				return bad("rolling back state mismatch")
880			}
881		case DeviceRollbackSucceeded:
882			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
883				return bad("rollback succeeded without success result")
884			}
885			if rb.ResultVersion != dd.RollbackTarget {
886				return bad("rollback version mismatch")
887			}
888			if _, ok := decodeObject(rb.ResultConfig); !ok {
889				return bad("rollback config invalid")
890			}
891		case DeviceRollbackFailed:
892			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
893				return bad("rollback failed without failure result")
894			}
895		case DeviceRollbackTimeout:
896			if dd.Phase != StageRollback {
897				return bad("rollback timeout phase mismatch")
898			}
899			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
900			if rb.HasResult {
901				return bad("rollback timeout with result")
902			}
903		default:
904			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
905			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
906			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
907			if dd.Install.HasResult && !dd.Install.Success {
908				return bad("install failure without rollback state")
909			}
910			if rb.Claimed || rb.HasResult {
911				return bad("rollback progressed without install failure")
912			}
913		}
914		return nil
915	}
916

