227		a1 := json.RawMessage(`{"a":1}`)
228		a2 := json.RawMessage(`{"a":2}`)
229		a3 := json.RawMessage(`{"a":3}`)
230		a9 := json.RawMessage(`{"a":9}`)
231		x1 := json.RawMessage(`{"x":1}`)
232	
233		cases := map[string]func(fixStore){
234			// 删掉修订号 1 的审计，只留修订号 2 与当前影子
235			"first audit missing": func(doc fixStore) {
