190		// 操作后来随截止超时：超时终态也不能掩盖。
191		t.Run("timed out device with out-of-window claim", func(t *testing.T) {
192			s := setupUpgrade(t, "d1")
193			spec := upSpec()
194			spec.Devices = []string{"d1"}
195			createCampaign(t, s, spec)
196			bringOnline(t, s, "d1")
197			if _, err := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute)); err != nil {
198				t.Fatalf("claim: %v", err)
199			}
200			if err := s.AdvanceCampaign(spec.ID, spec.Deadline); err != nil {
201				t.Fatal(err)
202			}
203			if cv := mustGetCampaign(s, spec.ID); !cv.Ended || findDevice(cv, "d1").Status != DeviceTimeout {
204				t.Fatalf("precondition: %+v", cv)
205			}
206			dir := s.dir
207			s.Close()
208			original := setOpClaimedAt(t, dir, spec.ID, "d1", "download", "2026-10-02T11:59:00Z")
209			assertReopenCorrupt(t, dir, original)
210		})
211	
212		// 不同时区写法表示的窗口外时刻仍须拒绝（19:59+08:00 即 11:59Z）。
213		t.Run("out-of-window instant across timezone refused", func(t *testing.T) {
214			_, dir, spec := setupDownloading(t)
215			original := setOpClaimedAt(t, dir, spec.ID, "d1", "download", "2026-10-02T19:59:00+08:00")
216			assertReopenCorrupt(t, dir, original)
217		})
218	}
219	
220	// TestRestoreClaimWindowAccepted 保护合法记录不被窗口核对误拒：窗口边界
221	// （含开始时刻）、窗口外完成的后续环节、尚未领取的缺省记录都必须正常打开，
222	// 且已领取操作的标识与待办保持原样。
223	func TestRestoreClaimWindowAccepted(t *testing.T) {
224		// 恰好到达窗口开始时刻的首次领取合法（窗口包含开始时刻）。
225		t.Run("claimed exactly at window start", func(t *testing.T) {
226			_, dir, spec := setupDownloading(t)
227			setOpClaimedAt(t, dir, spec.ID, "d1", "download", "2026-10-02T12:00:00Z")
228			s2, err := Open(dir)
229			if err != nil {
230				t.Fatalf("claim at window start must open: %v", err)
231			}
232			defer s2.Close()
233		})
234	
235		// 相同时刻的不同时区写法不能被判为窗口外：20:10+08:00 即 12:10Z。
236		t.Run("in-window instant across timezone notation", func(t *testing.T) {
237			_, dir, spec := setupDownloading(t)
238			setOpClaimedAt(t, dir, spec.ID, "d1", "download", "2026-10-02T20:10:00+08:00")
239			s2, err := Open(dir)
240			if err != nil {
241				t.Fatalf("same instant in another timezone must open: %v", err)
242			}
243			defer s2.Close()
244			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DeviceDownloading {
245				t.Fatalf("d1 progress lost")
246			}
247		})
248	
249		// 窗口内领取、窗口外（截止前）提交结果合法：结果接受时间不要求在窗口内。
250		t.Run("result accepted after window end reopens", func(t *testing.T) {
251			s := setupUpgrade(t, "d1")
252			spec := upSpec()
253			spec.Devices = []string{"d1"}
254			createCampaign(t, s, spec)
255			bringOnline(t, s, "d1")
256			dl, _ := s.Claim(spec.ID, "d1", upBase.Add(50*time.Minute))
257			if err := s.SubmitResult(OperationResult{
258				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
259				At: upBase.Add(70 * time.Minute), Success: true,
260			}); err != nil {
261				t.Fatal(err)
262			}
263			dir := s.dir
264			s.Close()
265			s2, err := Open(dir)
266			if err != nil {
267				t.Fatalf("result outside window must reopen: %v", err)
268			}
269			defer s2.Close()
270			if findDevice(mustGetCampaign(s2, spec.ID), "d1").Status != DeviceReady {
271				t.Fatalf("d1 must be ready")
272			}
273		})
274	
275		// 窗口内领取后，窗口外的重复查询返回同一操作：重查时间不要求在窗口内，
276		// 重开后已领取操作仍使用原标识、待办与已领取标记保持原样。
277		t.Run("re-query after window end keeps original operation", func(t *testing.T) {
278			s := setupUpgrade(t, "d1")
279			spec := upSpec()
280			spec.Devices = []string{"d1"}
281			createCampaign(t, s, spec)
282			bringOnline(t, s, "d1")
283			dl, _ := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute))
284			again, err := s.Claim(spec.ID, "d1", upBase.Add(80*time.Minute))
285			if err != nil || again == nil || again.ID != dl.ID {
286				t.Fatalf("re-query must return same op: %v %+v", err, again)
287			}
288			dir := s.dir
289			s.Close()
290			s2, err := Open(dir)
291			if err != nil {
292				t.Fatalf("re-queried operation must reopen: %v", err)
293			}
294			defer s2.Close()
295			w, err := s2.GetDeviceWork("d1")
296			if err != nil {
297				t.Fatal(err)
298			}
299			if w.Pending == nil || w.Pending.ID != dl.ID || !w.PendingClaimed {
300				t.Fatalf("claimed operation identity changed: %+v", w)
301			}
302		})
303	
304		// 尚未领取的操作不代表窗口外领取：等待下载、等待安装及未领取便
305		// 随截止超时的记录都按已有规则读取。
306		t.Run("unclaimed operations reopen", func(t *testing.T) {
307			s := setupUpgrade(t, "d1", "d2")
308			spec := upSpec()
309			spec.Devices = []string{"d1", "d2"}
310			spec.BatchSize = 1
311			createCampaign(t, s, spec)
312			bringOnline(t, s, "d1")
313			// d1 下载成功后等待安装（安装未领取）；d2 等待下载（未领取）。
314			dl, _ := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute))
315			if err := s.SubmitResult(OperationResult{
316				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
317				At: upBase.Add(11 * time.Minute), Success: true,
318			}); err != nil {
319				t.Fatal(err)
320			}
321			dir := s.dir
322			s.Close()
323			s2, err := Open(dir)
324			if err != nil {
325				t.Fatalf("unclaimed stages must reopen: %v", err)
326			}
327			defer s2.Close()
328			cv := mustGetCampaign(s2, spec.ID)
329			if findDevice(cv, "d1").Status != DeviceReady || findDevice(cv, "d2").Status != DevicePending {
330				t.Fatalf("pending states lost: %+v", cv.Devices)
331			}
332		})
333	
334		// 开启回滚的活动中回滚尚未领取（等待回滚）：缺省的回滚领取时间
335		// 不代表窗口外领取，正常打开。
336		t.Run("awaiting rollback without claim reopens", func(t *testing.T) {
337			s := setupUpgrade(t, "d1")
338			spec := upSpec()
339			spec.Devices = []string{"d1"}
340			spec.RollbackOnFailure = true
341			createCampaign(t, s, spec)
342			bringOnline(t, s, "d1")
343			dl, _ := s.Claim(spec.ID, "d1", upBase)
344			if err := s.SubmitResult(OperationResult{
345				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
346				At: upBase.Add(time.Minute), Success: true,
347			}); err != nil {
348				t.Fatal(err)
349			}
350			in, _ := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
351			if err := s.SubmitResult(OperationResult{
352				CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
353				At: upBase.Add(3 * time.Minute), Success: false, Reason: "install boom",
354			}); err != nil {
355				t.Fatal(err)
356			}
357			if cv := mustGetCampaign(s, spec.ID); findDevice(cv, "d1").Status != DeviceAwaitingRollback {
358				t.Fatalf("precondition: %+v", cv.Devices)
359			}
360			dir := s.dir
361			s.Close()
362			s2, err := Open(dir)
363			if err != nil {
364				t.Fatalf("awaiting rollback must reopen: %v", err)
365			}
366			defer s2.Close()
367			w, err := s2.GetDeviceWork("d1")
368			if err != nil {
369				t.Fatal(err)
370			}
371			if w.Pending == nil || w.Pending.Kind != StageRollback || w.PendingClaimed ||
372				w.Pending.TargetVersion != "v1" {
373				t.Fatalf("rollback pending changed: %+v", w)
374			}
375		})
376	
377		// 未开启回滚的既有活动：缺省的回滚操作不应被误判为已领取，
378		// 首次领取下载时锁定的回滚目标与设备影子也不受核对影响。
379		t.Run("non-rollback campaign default rollback op reopens", func(t *testing.T) {
380			_, dir, spec := setupReady(t)
381			s2, err := Open(dir)
382			if err != nil {
383				t.Fatalf("non-rollback campaign must reopen: %v", err)
384			}
385			defer s2.Close()
386			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
387			if d.Status != DeviceReady || d.RollbackTarget != "" {
388				t.Fatalf("non-rollback campaign changed: %+v", d)
389			}
390		})
391	
392		// 正常走完全流程的活动重开不受影响：终态、历史与影子版本保留。
393		t.Run("legal succeeded campaign reopens", func(t *testing.T) {
394			s := setupUpgrade(t, "d1")
395			spec := upSpec()
396			spec.Devices = []string{"d1"}
397			createCampaign(t, s, spec)
398			bringOnline(t, s, "d1")
399			finishDevice(t, s, spec, "d1", upBase.Add(10*time.Minute))
400			dir := s.dir
401			s.Close()
402			s2, err := Open(dir)
403			if err != nil {
404				t.Fatalf("legal campaign must reopen: %v", err)
405			}
406			defer s2.Close()
407			cv := mustGetCampaign(s2, spec.ID)
408			if !cv.Ended || cv.Status != CampaignSucceeded || len(cv.Results) != 2 {
409				t.Fatalf("campaign state changed: %+v", cv)
410			}
411			v, err := s2.Get("d1")
412			if err != nil {
413				t.Fatal(err)
414			}
415			if v.Version != "v2" {
416				t.Fatalf("shadow version changed: %+v", v)
417			}
418		})
419	}
